// Router: Déterminer le type d'événement
const items = [];

for (const item of $input.all()) {
  const data = item.json;

  if (data.callback_query) {
    // Bouton cliqué
    items.push({
      json: {
        event_type: 'callback',
        telegram_id: data.callback_query.from.id,
        chat_id: data.callback_query.message.chat.id,
        callback_id: data.callback_query.id,
        data: data.callback_query.data,
        text: "",
        from: data.callback_query.from,
        message_id: data.callback_query.message.message_id
      }
    });
  } else if (data.message) {
    // Message texte
    items.push({
      json: {
        event_type: 'message',
        telegram_id: data.message.from.id,
        chat_id: data.message.chat.id,
        text: data.message.text || '',
        data: "",
        from: data.message.from

      }
    });
  }
}

return items;

// Merge: Combiner les deux chemins (avec/sans auth)
const items = $input.all();
return items;

// Parser les callbacks (boutons cliqués)
const items = [];

for (const item of $input.all()) {
  const data = $('Router: Events').first().json.data;

  // Format: add_to_cart_PRODUCTID ou checkout ou clear_cart ou pay_order_ORDERID
  if (data.startsWith('add_to_cart_')) {
    const productId = parseInt(data.replace('add_to_cart_', ''));
    items.push({
      json: {
        ...item.json,
        action: 'add_to_cart',
        product_id: productId
      }
    });
  } else if (data === 'checkout') {
    items.push({
      json: {
        ...item.json,
        action: 'checkout'
      }
    });
  } else if (data === 'clear_cart') {
    items.push({
      json: {
        ...item.json,
        action: 'clear_cart'
      }
    });
  } else if (data === 'view_cart') {
    items.push({
      json: {
        ...item.json,
        action: 'view_cart'
      }
    });
  } else if (data.startsWith('pay_order_')) {
    const orderId = parseInt(data.replace('pay_order_', ''));
    items.push({
      json: {
        ...item.json,
        action: 'pay_order',
        order_id: orderId
      }
    });
  }
}

return items;

// Gérer le panier en cache
const items = [];
const staticData = $getWorkflowStaticData('global');

if (!staticData.carts) {
  staticData.carts = {};
}

for (const item of $input.all()) {
  items.push({
    json: {
      ...item.json,
      cart: $input.first().json.product_id,
      cart_size: "",
      message: `✅ Produit ajouté au panier!\n\nArticles dans le panier: \n\nUtilisez /cart pour voir votre panier.`
    }
  });
}

return items;

// Récupérer tous les items du panier depuis l'entrée
const cart = $input.all().map(i => i.json);

// Préparation du message
let message = '🛒 VOTRE PANIER\n';
message += '═'.repeat(40) + '\n\n';

if (cart.length === 0) {
	message += 'Votre panier est vide.\n\n';
	message += 'Ajoutez des articles avec /menu.\n';

	return [
		{
			json: {
				error: true,
				message,
				cart: [],
				has_items: false,
				reply_markup: {
					inline_keyboard: [
						[
							{ text: '🍽️ Retour au menu', callback_data: 'back_to_menu' }
						]
					]
				}
			}
		}
	];
}

// Liste des produits
for (const p of cart) {
	message += `• Produit #${p.product_id} x${p.quantity}\n`;
}

// Total
const totalItems = cart.reduce((sum, p) => sum + p.quantity, 0);

message += '\n';
message += '═'.repeat(40) + '\n';
	message += `Total articles: ${totalItems}\n\n`;
message += 'Utilisez les boutons ci-dessous pour gérer votre panier.';

// Boutons Telegram
const keyboard = [
	[
		{ text: '💳 Commander maintenant', callback_data: 'checkout' },
		{ text: '🗑️ Vider le panier', callback_data: 'clear_cart' }
	],
	[
		{ text: '🍽️ Retour au menu', callback_data: 'back_to_menu' }
	]
];

// Retour unique
return [
	{
		json: {
			error: false,
			message,
			cart,
            token: $('Action: Checkout?').first().json.token,
            telegram_id: $input.first().json.telegram_id,
            chat_id: $('Router: Events').first().json.chat_id,
            callback_id: $('Router: Events').first().json.callback_id,
			has_items: true,
			reply_markup: {
				inline_keyboard: keyboard
			}
		}
	}
];

// Vider le panier après commande
const items = [];

for (const item of $input.all()) {
  // Formater le message de confirmation
  const order = item.json;
  let message = '✅ Commande créée avec succès!\n\n';
  message += `📦 Commande: ${order.order_number}\n`;
  message += `💰 Total: ${order.total_amount} FCFA\n`;
  message += `📍 Status: ${order.status}\n\n`;
  message += 'Articles:\n';

  order.items.forEach(item => {
    message += `• ${item.product.name} x${item.quantity} - ${item.unit_price} FCFA\n`;
  });

  message += '\n🔔 Vous recevrez une notification quand votre commande sera prête.';

  items.push({
    json: {
      ...item.json,
      formatted_message: message
    }
  });
}

return items;

// Message de bienvenue
const items = [];

for (const item of $input.all()) {
  const firstName =  $('Get row(s)').first().json.firstName;

  const message = `👋 Bonjour ${firstName}!\n\nBienvenue dans notre restaurant!\n\nCommandes disponibles:\n🍽️ /menu - Voir le menu\n🛒 /cart - Voir mon panier\n💰 /wallet - Mon portefeuille\n📦 /orders - Mes commandes\n💳 /transactions - Mes transactions\n\nCliquez sur /menu pour commencer!`;

  items.push({
    json: {
      ...item.json,
      message: message
    }
  });
}

return items;

// Formater le menu avec boutons inline
const items = [];

for (const item of $input.all()) {
  const menuData = item.json;
  const menu = menuData.menu;

  let message = '🍽️ MENU DU RESTAURANT\n';
  message += '═'.repeat(40) + '\n\n';

  const keyboard = [];

  menu.forEach(category => {
    message += `📂 ${category.name.toUpperCase()}\n`;
    message += '-'.repeat(40) + '\n';

    category.products.forEach(product => {
      message += `${product.name}\n`;
      message += `💰 ${product.price} FCFA\n\n`;

      // Ajouter bouton pour ce produit
      keyboard.push([{
        text: `🛒 ${product.name} - ${product.price} FCFA`,
        callback_data: `add_to_cart_${product.id}`
      }]);
    });

    message += '\n';
  });

  message += '═'.repeat(40) + '\n';
  message += `Total: ${menuData.total_products} produits disponibles\n\n`;
  message += '👆 Cliquez sur un produit pour l\'ajouter au panier';

  // Ajouter boutons de gestion du panier
  keyboard.push([
    { text: '🛒 Voir mon panier', callback_data: 'view_cart' },
    { text: '💳 Commander', callback_data: 'checkout' }
  ]);

  items.push({
    json: {
      ...item.json,
      message: message,
      reply_markup: {
        inline_keyboard: keyboard
      }
    }
  });
}

return items;

// Envoyer un message par plat avec son bouton d'ajout au panier
const items = [];

for (const item of $input.all()) {
  const TELEGRAM_BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN;
  const chatId = $('Router: Events').first().json.chat_id;
  const menuData = item.json;
  const menu = menuData.menu;

  // Envoyer le titre du menu
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
    json: true,
    body: {
      chat_id: chatId,
      text: `🍽️ MENU DU RESTAURANT\n${'═'.repeat(40)}\n\nTotal: ${menuData.total_products} produits disponibles`
    }
  });

  // Envoyer chaque plat par catégorie
  for (const category of menu) {
    // Envoyer le titre de catégorie
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
      json: true,
      body: {
        chat_id: chatId,
        text: `📂 ${category.name.toUpperCase()}\n${'-'.repeat(40)}`
      }
    });

    // Envoyer chaque produit avec son bouton
    for (const product of category.products) {
      const productMsg = `${product.name}\n💰 ${product.price} FCFA`;

      await this.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
        json: true,
        body: {
          chat_id: chatId,
          text: productMsg,
          reply_markup: {
            inline_keyboard: [
              [{ text: `🛒 Ajouter au panier`, callback_data: `add_to_cart_${product.id}` }]
            ]
          }
        }
      });
    }
  }

  // Envoyer les boutons de gestion du panier
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
    json: true,
    body: {
      chat_id: chatId,
      text: '👆 Choisissez vos plats puis gérez votre panier:',
      reply_markup: {
        inline_keyboard: [
          [
            { text: '🛒 Voir mon panier', callback_data: 'view_cart' },
            { text: '💳 Commander', callback_data: 'checkout' }
          ]
        ]
      }
    }
  });

  items.push({ json: { success: true } });
}

return items;

// Récupérer tous les items envoyés en entrée
const inputItems = $input.all().map(i => i.json);

// Si aucun produit
let message = '🛒 VOTRE PANIER\n';
message += '═'.repeat(40) + '\n\n';

if (inputItems.length === 0) {
	message += 'Votre panier est vide.\n\n';
	message += 'Ajoutez des articles avec /menu.\n';

	return [
		{
			json: {
				message,
				has_items: false,
				reply_markup: {
					inline_keyboard: [
						[
							{ text: '🍽️ Retour au menu', callback_data: 'back_to_menu' }
						]
					]
				}
			}
		}
	];
}

// Construire le message panier
for (const p of inputItems) {
	message += `• Produit #${p.product_id}  x${p.quantity}\n`;
}

// Total
const totalItems = inputItems.reduce((sum, p) => sum + p.quantity, 0);

message += '\n';
message += '═'.repeat(40) + '\n';
message += `Total articles: ${totalItems}\n\n`;
message += 'Utilisez les boutons ci-dessous pour gérer votre panier.';

// Inline keyboard Telegram
const keyboard = [
	[
		{ text: '💳 Commander maintenant', callback_data: 'checkout' },
		{ text: '🗑️ Vider le panier', callback_data: 'clear_cart' }
	],
	[
		{ text: '🍽️ Retour au menu', callback_data: 'back_to_menu' }
	]
];

// Retour unique
return [
	{
		json: {
			message,
            chat_id: $('Router: Events').first().json.chat_id,
            event_type: $('Router: Events').first().json.event_type,
            data: $('Router: Events').first().json.data,
            callback_id: $('Router: Events').first().json.callback_id,
			has_items: true,
			reply_markup: {
				inline_keyboard: keyboard
			}
		}
	}
];

// Préparer notification pour l'utilisateur
const items = [];

for (const item of $input.all()) {
  const order = item.json;

  let message = '📦 Mise à jour de commande\n\n';
  message += `Commande: ${order.order_number}\n`;
  message += `Status: En préparation\n`;
  message += `Total: ${order.total_amount} FCFA\n\n`;
  message += 'Votre commande est en cours de préparation!\n';
  message += 'Vous serez notifié quand elle sera prête.';

  items.push({
    json: {
      ...item.json,
      telegram_id: order.user.telegram_id,
      message: message
    }
  });
}

return items;

// Format orders list for Telegram
const items = [];

for (const item of $input.all()) {
  const orders = item.json.results || item.json;

  let message = '📦 VOS COMMANDES\n';
  message += '═'.repeat(40) + '\n\n';

  if (!orders || orders.length === 0) {
    message += 'Vous n\'avez aucune commande.\n\n';
    message += 'Utilisez /menu pour commander!';

    items.push({
      json: {
        ...item.json,
        message: message,
        has_orders: false
      }
    });
    continue;
  }

  const keyboard = [];

  // Handle both array and paginated response
  const orderList = Array.isArray(orders) ? orders : (orders.results || []);

  orderList.forEach((order, index) => {
    // Format status with emoji
    let statusEmoji = '⏳';
    let statusLabel = 'En attente';
    if (order.status === 'PENDING') {
      statusEmoji = '⏳';
      statusLabel = 'En attente';
    } else if (order.status === 'CONFIRMED') {
      statusEmoji = '✅';
      statusLabel = 'Confirmée';
    } else if (order.status === 'PREPARING') {
      statusEmoji = '🔄';
      statusLabel = 'En préparation';
    } else if (order.status === 'READY') {
      statusEmoji = '🚀';
      statusLabel = 'Prête';
    } else if (order.status === 'DELIVERED') {
      statusEmoji = '✅';
      statusLabel = 'Livrée';
    } else if (order.status === 'CANCELLED') {
      statusEmoji = '❌';
      statusLabel = 'Annulée';
    }

    message += `Commande #${order.order_number}\n`;
    message += `Status: ${statusEmoji} ${statusLabel}\n`;
    message += `💰 Total: ${order.formatted_total || (order.total_amount + ' FCFA')}\n`;
    message += `📅 Date: ${new Date(order.created_at).toLocaleDateString('fr-FR', {day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'})}\n`;

    // Add payment status
    if (!order.is_paid) {
      message += `💳 Statut paiement: ❌ Non payée\n`;
      // Add pay button for unpaid orders
      keyboard.push([{
        text: `💳 Payer cette commande`,
        callback_data: `pay_order_${order.id}`
      }]);
    } else {
      message += `💳 Statut paiement: ✅ Payée\n`;
    }

    // Show order items
    if (order.items && order.items.length > 0) {
      message += '\nItems:\n';
      order.items.forEach(item => {
        message += `• ${item.product.name} x${item.quantity}\n`;
      });
    }

    message += '\n' + '-'.repeat(40) + '\n\n';
  });

  message += '═'.repeat(40) + '\n';
  message += `Total: ${orderList.length} commande(s)`;

  items.push({
    json: {
      ...item.json,
      message: message,
      has_orders: true,
      has_buttons: keyboard.length > 0,
      reply_markup: {
        inline_keyboard: keyboard
      }
    }
  });
}

return items;

// Envoyer un message par commande avec son bouton de paiement
const items = [];

for (const item of $input.all()) {
  const TELEGRAM_BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN;
  const chatId = $('Switch').first().json.chat_id;
  const orders = item.json.results || item.json;

  if (!orders || orders.length === 0) {
    // Envoyer message "aucune commande"
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
      json: true,
      body: {
        chat_id: chatId,
        text: '📦 VOS COMMANDES\n' + '═'.repeat(40) + '\n\n' +
              'Vous n\'avez aucune commande.\n\n' +
              'Utilisez /menu pour commander!'
      }
    });
    items.push({ json: { success: true } });
    continue;
  }

  // Envoyer le titre
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
    json: true,
    body: {
      chat_id: chatId,
      text: `📦 VOS COMMANDES\n${'═'.repeat(40)}\n\nTotal: ${orders.length} commande(s)`
    }
  });

  // Envoyer chaque commande séparément
  const orderList = Array.isArray(orders) ? orders : (orders.results || []);

  for (const order of orderList) {
    // Format status
    let statusEmoji = '⏳';
    let statusLabel = 'En attente';
    if (order.status === 'PENDING') { statusEmoji = '⏳'; statusLabel = 'En attente'; }
    else if (order.status === 'CONFIRMED') { statusEmoji = '✅'; statusLabel = 'Confirmée'; }
    else if (order.status === 'PREPARING') { statusEmoji = '🔄'; statusLabel = 'En préparation'; }
    else if (order.status === 'READY') { statusEmoji = '🚀'; statusLabel = 'Prête'; }
    else if (order.status === 'DELIVERED') { statusEmoji = '✅'; statusLabel = 'Livrée'; }
    else if (order.status === 'CANCELLED') { statusEmoji = '❌'; statusLabel = 'Annulée'; }

    let orderMsg = `Commande #${order.order_number}\n`;
    orderMsg += `Status: ${statusEmoji} ${statusLabel}\n`;
    orderMsg += `💰 Total: ${order.formatted_total || (order.total_amount + ' FCFA')}\n`;
    orderMsg += `📅 Date: ${new Date(order.created_at).toLocaleDateString('fr-FR', {day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'})}\n`;
    orderMsg += `💳 Statut paiement: ${!order.is_paid ? '❌ Non payée' : '✅ Payée'}\n`;

    if (order.items && order.items.length > 0) {
      orderMsg += '\nItems:\n';
      order.items.forEach(itm => {
        orderMsg += `• ${itm.product.name} x${itm.quantity}\n`;
      });
    }

    const body = {
      chat_id: chatId,
      text: orderMsg
    };

    // Ajouter bouton de paiement si non payée
    if (!order.is_paid) {
      body.reply_markup = {
        inline_keyboard: [
          [{ text: '💳 Payer cette commande', callback_data: `pay_order_${order.id}` }]
        ]
      };
    }

    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
      json: true,
      body: body
    });
  }

  items.push({ json: { success: true } });
}

return items;

// Format transactions list for Telegram
const items = [];

for (const item of $input.all()) {
  const transactions = item.json.results || item.json;

  let message = '📊 HISTORIQUE DES TRANSACTIONS\n';
  message += '═'.repeat(40) + '\n\n';

  if (!transactions || transactions.length === 0) {
    message += 'Aucune transaction trouvée.\n\n';
    message += 'Utilisez /wallet pour voir votre portefeuille.';

    items.push({
      json: {
        ...item.json,
        message: message
      }
    });
    continue;
  }

  // Handle both array and paginated response
  const txList = Array.isArray(transactions) ? transactions : (transactions.results || []);

  txList.slice(0, 10).forEach((tx, index) => {
    // Format type with emoji
    const typeEmoji = tx.type === 'CREDIT' ? '💰' : '💸';
    const typeLabel = tx.type === 'CREDIT' ? 'Crédit' : 'Débit';

    // Format status with emoji
    let statusEmoji = '⏳';
    if (tx.status === 'COMPLETED') statusEmoji = '✅';
    else if (tx.status === 'FAILED') statusEmoji = '❌';

    message += `${typeEmoji} ${typeLabel}: ${tx.formatted_amount || (tx.amount + ' FCFA')}\n`;

    if (tx.description) {
      message += `   ${tx.description}\n`;
    }

    message += `   ${new Date(tx.created_at).toLocaleDateString('fr-FR', {day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'})}\n`;
    message += `   Status: ${statusEmoji} ${tx.status}\n`;

    if (tx.transaction_id) {
      message += `   ID: ${tx.transaction_id}\n`;
    }

    message += '\n' + '-'.repeat(40) + '\n\n';
  });

  message += '═'.repeat(40) + '\n';

  const totalCount = Array.isArray(transactions) ? transactions.length : (transactions.count || txList.length);
  if (totalCount > 10) {
    message += `Affichage des 10 dernières transactions sur ${totalCount} au total`;
  } else {
    message += `Total: ${totalCount} transaction(s)`;
  }

  items.push({
    json: {
      ...item.json,
      message: message
    }
  });
}

return items;

// Format wallet balance for Telegram
const items = [];

for (const item of $input.all()) {
  const wallet = item.json;

  let message = '💰 VOTRE PORTEFEUILLE\n';
  message += '═'.repeat(40) + '\n\n';

  message += `💵 Solde actuel: ${wallet.formatted_balance || wallet.balance + ' FCFA' || '0 FCFA'}\n\n`;

  message += '═'.repeat(40) + '\n';
  message += 'Utilisez /transactions pour voir l\'historique complet.';

  items.push({
    json: {
      ...item.json,
      message: message
    }
  });
}

return items;

// Format payment confirmation
const items = [];

for (const item of $input.all()) {
  let message = '';

  // Check if payment was successful (check for error field)
  if (item.json.error) {
    // Payment failed
    message = '❌ PAIEMENT ÉCHOUÉ\n\n';
    message += item.json.error + '\n\n';

    if (item.json.current_balance && item.json.required_amount) {
      message += `Solde actuel: ${item.json.current_balance}\n`;
      message += `Montant requis: ${item.json.required_amount}\n\n`;
    }

    message += 'Veuillez recharger votre compte ou vérifiez votre solde avec /wallet';
  } else if (item.json.message || item.json.transaction) {
    // Payment successful
    message = '✅ PAIEMENT EFFECTUÉ !\n\n';
    message += `Commande: #${item.json.order_number || 'N/A'}\n`;

    if (item.json.transaction) {
      message += `Montant payé: ${item.json.transaction.formatted_amount || (item.json.transaction.amount + ' FCFA')}\n`;
    }

    message += `\nNouveau solde: ${item.json.remaining_balance || 'N/A'}\n\n`;
    message += 'Merci pour votre paiement !';
  } else {
    // Unknown error
    message = '❌ Une erreur est survenue\n\n';
    message += 'Veuillez réessayer ou contacter le support.';
  }

  items.push({
    json: {
      ...item.json,
      message: message,
      callback_id: $('Router: Events').item.json.callback_id
    }
  });
}

return items;
